INSERT OR IGNORE INTO categories (id, slug, name, parent, description_html, second_html, seo_title, seo_desc) VALUES
(4009, 'eroticke-pomucky', 'Erotické pomůcky', 0,
 '<p><strong>Erotické pomůcky a hračky</strong> pro ženy, muže i páry na jednom místě. Srovnáváme ceny z ověřených českých e-shopů, takže u každé pomůcky uvidíte, kde je nejlevnější a skladem. Vyberte si podle toho, pro koho pomůcku hledáte, nebo podle druhu.</p>',
 '<h2>Jak vybrat erotickou pomůcku</h2><p>Nejdřív si ujasněte, <strong>pro koho</strong> pomůcku kupujete a <strong>k čemu</strong> má sloužit. Pro sólo hru se hodí jiné věci než pro společný večer a pro začátek stačí jednoduchý, tichý a snadno omyvatelný model. Dražší není automaticky lepší: rozhoduje velikost, materiál a způsob nabíjení.</p><h3>Podle toho, pro koho pomůcka je</h3><ul><li><a href="/eroticke-pomucky-pro-zeny/">Erotické pomůcky pro ženy</a> – vibrátory, tlakové stimulátory, venušiny kuličky a vibrační vajíčka.</li><li><a href="/eroticke-pomucky-pro-muze/">Erotické pomůcky pro muže</a> – masturbátory, erekční kroužky, vakuové pumpy a pomůcky pro masáž prostaty.</li><li><a href="/eroticke-pomucky-pro-pary/">Erotické pomůcky pro páry</a> – párové vibrátory, erotické hry, kondomy pro páry a sady.</li></ul><h3>Podle druhu</h3><ul><li><a href="/vibratory/">Vibrátory</a> a <a href="/dilda/">dilda</a> – základ většiny sbírek.</li><li><a href="/umele-vaginy-a-masturbatory/">Masturbátory a umělé vaginy</a> – od jednorázových vajíček po realistické modely.</li><li><a href="/analni-koliky/">Anální kolíky</a> a <a href="/doplnky-k-analnimu-sexu/">doplňky k análnímu sexu</a> – začněte malými modely a dostatkem lubrikantu.</li><li><a href="/erekcni-krouzky-na-penis-a-varlata/">Erekční kroužky</a>, <a href="/vakuove-pumpy/">vakuové pumpy</a> a <a href="/venusiny-kulicky/">venušiny kuličky</a>.</li><li><a href="/eroticke-pradlo/">Erotické prádlo</a>, <a href="/fetis-kink/">fetiš a BDSM</a> a <a href="/eroticke-pouta/">erotická pouta</a>.</li><li><a href="/lubrikacni-gely-a-oleje/">Lubrikační gely</a>, <a href="/kondomy/">kondomy</a> a <a href="/pece-o-eroticke-pomucky/">péče o erotické pomůcky</a>.</li></ul><h3>Na co se při výběru dívat</h3><ul><li><strong>Materiál</strong> – tělu bezpečný silikon, sklo nebo kov se dají dobře čistit; porézním materiálům věnujte víc péče.</li><li><strong>Nabíjení a hlučnost</strong> – USB nabíjení je pohodlné, u tichých modelů nikdo nic nezaslechne.</li><li><strong>Voděodolnost</strong> – usnadňuje čištění a hodí se do vany.</li><li><strong>Velikost a tvar</strong> – začátečníci často volí menší a méně intenzivní modely.</li><li><strong>Čištění a skladování</strong> – hygienu a bezpečnost pomůcek řešíme v samostatné kategorii o péči.</li></ul><p>Ceny a dostupnost se v obchodech mění, proto u každého produktu porovnáváme nabídky více e-shopů. Pomůcky jsou určené pouze pro dospělé.</p>',
 'Erotické pomůcky a hračky: srovnání cen z e-shopů | Eroka',
 'Erotické pomůcky a sex hračky pro ženy, muže i páry: vibrátory, masturbátory, dilda, prádlo i BDSM. Porovnejte ceny z ověřených českých e-shopů.'),
(4010, 'eroticke-podprsenky', 'Erotické podprsenky', 105,
 '<p><strong>Erotické podprsenky</strong> z krajky, síťoviny, koženky i latexu – otevřené, push-up, s podvazky nebo jako součást kompletu. Ceny porovnáváme u ověřených obchodů a u každého kousku uvidíte, kde je nejlevnější a skladem.</p>',
 '<h2>Jak vybrat erotickou podprsenku</h2><ul><li><strong>Velikost a obvod pod prsy</strong> – tabulky obchodů se liší, proměřte obvod pod prsy a přes prsa a porovnejte je s tabulkou u konkrétního modelu.</li><li><strong>Materiál</strong> – krajka a síťovina jsou jemné a prodyšné, koženka a latex drží tvar, ale vyžadují lubrikant při oblékání a jinou péči.</li><li><strong>Střih</strong> – otevřené košíčky, push-up, bralette bez kostic nebo model s ramínky na zapínání.</li><li><strong>Komplet</strong> – <a href="/eroticke-komplety-spodniho-pradla/">komplety spodního prádla</a> a <a href="/podvazky-a-podvazkove-pasy/">podvazkové pasy</a> se hodí k sobě.</li></ul><p>Plnější postavy najdou širší nabídku v kategorii <a href="/eroticke-pradlo-plus-size/">erotické prádlo plus size</a>. Celý sortiment je v kategorii <a href="/damske-eroticke-pradlo/">dámské erotické prádlo</a>.</p>',
 'Erotické podprsenky: krajkové, push-up, otevřené – srovnání cen | Eroka',
 'Erotické podprsenky z krajky, síťoviny a koženky: otevřené, push-up i v kompletu. Porovnejte ceny a velikosti z ověřených českých e-shopů.'),
(4011, 'masturbacni-vajicka', 'Masturbační vajíčka', 100,
 '<p><strong>Masturbační vajíčka</strong> jsou malé, pružné masturbátory ve tvaru vajíčka, například TENGA Egg, Satisfyer Egg nebo Ezy Egg. Prodávají se po jednom i v sadách s různými vnitřními strukturami. Ceny porovnáváme u ověřených obchodů.</p>',
 '<h2>Jak vybrat masturbační vajíčko</h2><ul><li><strong>Struktura uvnitř</strong> – hladké, žebrované, s výstupky nebo s hlubšími vlnami; sady (Variety Pack, Combo) jsou nejlepší cesta, jak najít svou oblíbenou.</li><li><strong>Velikost</strong> – vajíčka jsou kompaktní a nenápadná, při cestování zaberou málo místa.</li><li><strong>Lubrikant</strong> – používejte lubrikant na vodní bázi, pokud výrobce neurčí jinak.</li><li><strong>Čištění</strong> – vajíčko po použití vypláchněte, osušte a skladujte podle pokynů výrobce; informace o opakovaném použití najdete u konkrétní značky.</li></ul><p>Větší nabídku najdete mezi <a href="/umele-vaginy-a-masturbatory-tenga/">masturbátory TENGA</a> a v celé kategorii <a href="/umele-vaginy-a-masturbatory/">umělé vaginy a masturbátory</a>.</p>',
 'Masturbační vajíčka: TENGA Egg a další – srovnání cen | Eroka',
 'Masturbační vajíčka TENGA Egg, Satisfyer Egg, Ezy Egg a další. Jednotlivě i v sadách – porovnejte ceny z ověřených e-shopů.');

